<script setup>
import {ref,computed} from 'vue';import {store,hoy,nombreCurso,estado} from '../store';const mes=ref(new Date()),seleccion=ref(hoy());const agenda=computed(()=>store.tareas.filter(t=>t.fecha===seleccion.value));const titulo=computed(()=>mes.value.toLocaleDateString('es-PE',{month:'long',year:'numeric'}));const dias=computed(()=>{const y=mes.value.getFullYear(),m=mes.value.getMonth(),inicio=(new Date(y,m,1).getDay()+6)%7,n=new Date(y,m+1,0).getDate();return [...Array(inicio).fill(null),...Array.from({length:n},(_,i)=>({numero:i+1,fecha:hoy(new Date(y,m,i+1))}))]});function cambiar(n){mes.value=new Date(mes.value.getFullYear(),mes.value.getMonth()+n,1)}
</script><template><div class="page-heading"><div><div class="eyebrow">AGENDA</div><h2>Calendario académico</h2><p>Selecciona un día para consultar tus actividades.</p></div><button class="btn btn-outline-primary" @click="mes=new Date();seleccion=hoy()">Hoy</button></div><div class="card p-3"><div class="d-flex justify-content-between align-items-center mb-3"><button class="btn btn-outline-secondary" @click="cambiar(-1)">Anterior</button><h5 class="text-capitalize">{{titulo}}</h5><button class="btn btn-outline-secondary" @click="cambiar(1)">Siguiente</button></div><div class="calendar"><div v-for="d in ['Lun','Mar','Mié','Jue','Vie','Sáb','Dom']" class="text-center text-secondary small">{{d}}</div><div v-for="(d,i) in dias" :key="i" class="day" :class="{'border-primary':d?.fecha===seleccion}" @click="d&&(seleccion=d.fecha)"><template v-if="d"><button class="btn btn-sm p-0" @click="seleccion=d.fecha">{{d.numero}}</button><div v-for="t in store.tareas.filter(t=>t.fecha===d.fecha)" :key="t.id" class="event">{{t.nombre}}</div></template></div></div></div><div class="card p-4 mt-3"><h5>Agenda del {{seleccion}}</h5><p v-if="!agenda.length" class="empty-state">Sin actividades para esta fecha.</p><div v-for="t in agenda" :key="t.id" class="task-row"><div class="flex-grow-1"><strong>{{t.nombre}}</strong><div class="small text-secondary">{{nombreCurso(t.curso)}} · {{estado(t)}}</div></div><RouterLink :to="'/actividades?editar='+t.id" class="btn btn-sm btn-outline-primary">Ver actividad</RouterLink></div></div></template>